// addDemoEssays gives the essay to a demo cohort of the platoons 101 and 102
// twice: the early one is closed, the final one is open. The essays are handed in.
func (a *Service) addDemoEssays(db *model.Database, created string, now time.Time, teacherID string) {
	form, ok := a.forms[essayForm]
	if !ok {
		return
	}
	cohort := model.Cohort{ID: uuid(), VUC: "Демонстрационный ВУЦ", Name: "Выпуск 2027", Year: 2027, CreatedBy: teacherID, Created: created}
	for _, p := range db.Platoons {
		if p.Name == "101" || p.Name == "102" {
			cohort.PlatoonIDs = append(cohort.PlatoonIDs, p.ID)
		}
	}
	db.Cohorts = append(db.Cohorts, cohort)
	early := model.Assignment{ID: uuid(), Title: "Эссе по итогам первого семестра", FormID: form.ID, CohortID: cohort.ID, Active: false, Created: now.Add(-60 * 24 * time.Hour).Format(time.RFC3339), OwnerID: teacherID}
	final := model.Assignment{ID: uuid(), Title: "Выпускное эссе", FormID: form.ID, CohortID: cohort.ID, Active: true, Created: now.Add(-4 * 24 * time.Hour).Format(time.RFC3339), OwnerID: teacherID}
	db.Assignments = append(db.Assignments, early, final)
	students := []model.Account{}
	for _, account := range db.Students {
		if cohortStudent(cohort, account) {
			students = append(students, account)
		}
	}
	for n, essay := range demoEssays {
		if essay.Student >= len(students) {
			continue
		}
		as, done := early, now.Add(-55*24*time.Hour)
		if essay.Final {
			as, done = final, now.Add(-2*24*time.Hour)
		}
		done = done.Add(time.Duration(n) * time.Minute)
		stamp := done.Format(time.RFC3339)
		submission := model.FormSubmission{ID: uuid(), FormID: form.ID, FormVersion: form.Version, StudentID: students[essay.Student].ID, AssignmentID: as.ID, Created: stamp, Updated: stamp, Consent: true, ConsentAt: stamp, Completed: true, CompletedAt: stamp, SavedSections: []string{}, Answers: map[string]json.RawMessage{}}
		for _, section := range form.Sections {
			submission.SavedSections = append(submission.SavedSections, section.ID)
			for _, field := range section.Fields {
				text, _ := json.Marshal(essay.Answers[field.Number])
				submission.Answers[field.ID] = text
			}
		}
		db.Submissions = append(db.Submissions, submission)
	}
}
